"""Exercise Board1 V1 bytes generated by the production C recorder."""

import hashlib
import json
import os
from pathlib import Path
import struct
import subprocess
import sys
import tempfile
import unittest
import zlib


TOOL = Path(__file__).resolve().parents[1]
ADC = 128
ENCODER = ADC + 42 * 100
FIXTURE = Path(os.environ["FOC_CAPTURE_FIXTURE"])


class CaptureTests(unittest.TestCase):
    def setUp(self):
        folder = tempfile.TemporaryDirectory()
        self.addCleanup(folder.cleanup)
        self.path = Path(folder.name)
        self.raw = self.path / "image.bin"
        self.meta_path = self.path / "metadata.json"
        self.witness_path = self.path / "witness.json"
        subprocess.run([str(FIXTURE), str(self.raw)], check=True, capture_output=True, timeout=10)
        self.meta = {"format_version": 1, "source": "HOST_VIRTUAL", "capture_id": 17,
                     "build_tag": 0, "firmware_sha256": None, "raw_sha256": self.digest(),
                     "identity": dict(device_id=11, motor_id=12, encoder_id=13, frame_id=14),
                     "origin_note": "Synthetic observations from the production C recorder test"}
        start, end = struct.unpack_from("<2I", self.raw.read_bytes(), 36)
        self.witness = {"format_version": 1, "stage": "ADC_ZERO", "capture_id": 17,
                        "raw_sha256": self.meta["raw_sha256"], "firmware_sha256": None,
                        "covers_start_us": start, "covers_end_us": end, "witness_source": "HOST_VIRTUAL",
                        "independent_zero_current": True, "sampling_window_verified": True, "amp_per_count": 0.001,
                        "instrument": {"id": "fixture", "model": "deterministic fixture",
                                       "calibration": "defined by the test"},
                        "evidence_reference": "The deterministic test defines independent zero current."}
        self.archive = self.path / "archive"

    def digest(self):
        return hashlib.sha256(self.raw.read_bytes()).hexdigest()

    def modify(self, changes, clear=None):
        raw = bytearray(self.raw.read_bytes())
        for offset, value in changes:
            struct.pack_into("<I", raw, offset, value)
        if clear:
            start, size = clear
            raw[start:start + size] = bytes(size)
        struct.pack_into("<I", raw, 124, 0)
        struct.pack_into("<I", raw, 124, zlib.crc32(raw))
        self.raw.write_bytes(raw)
        self.meta["raw_sha256"] = self.witness["raw_sha256"] = self.digest()

    def invoke(self, use_witness=False):
        self.meta_path.write_text(json.dumps(self.meta), encoding="utf-8")
        options = []
        if use_witness:
            self.witness_path.write_text(json.dumps(self.witness), encoding="utf-8")
            options = ["--qualification", str(self.witness_path)]
        process = subprocess.run(
            [sys.executable, "-B", str(TOOL / "board_capture.py"), "import", str(self.raw),
             "--metadata", str(self.meta_path), "--out", str(self.archive), *options],
            capture_output=True, text=True, timeout=20)
        self.assertTrue(process.stdout, process.stderr)
        report = json.loads((self.archive / "diagnostic.json").read_bytes())
        self.assertEqual((self.archive / "capture.bin").read_bytes(), self.raw.read_bytes())
        self.assertEqual((self.archive / "source.json").read_bytes(), self.meta_path.read_bytes())
        return process.returncode, json.loads(process.stdout), report

    def assert_rejected(self, reason, witness=False):
        status, output, report = self.invoke(witness)
        self.assertEqual(status, 2, output)
        self.assertEqual(output["reason"], reason, output)
        self.assertEqual(report["rejection"]["reason"], reason)
        self.assertFalse((self.archive / "trace").exists())
        return report

    def test_pristine_diagnostic(self):
        result, output, report = self.invoke()
        self.assertEqual(result, 0, output)
        self.assertEqual(output["provenance"], "PROVENANCE_DECLARED")
        self.assertTrue(output["health"]["complete"])
        self.assertEqual(len(report["adc"]), 40)
        self.assertEqual(len(report["encoder"]), 16)
        self.assertEqual(report["adc"][0]["ranks"], [1241, 2052, 2048, 2042])
        self.assertEqual(report["encoder"][15]["raw_word"], 16399)
        self.assertGreater(report["header"]["start_us"], report["header"]["end_us"])
        self.assertEqual(report["health"]["software_inhibit_confirmed_rows"], 40)
        for key in ("ADC_ZERO", "ENCODER_LUT_ROTOR_OFFSET", "R_L", "J_B", "K_D"):
            self.assertTrue(report["stage_status"][key].endswith("REQUIRED"))
        self.assertFalse((self.archive / "trace").exists())

    def assert_trace(self, expected_source):
        result, output, _ = self.invoke(use_witness=True)
        self.assertEqual(result, 0, output)
        self.assertEqual(output["status"], ("TRACE_PREPARED_PROVENANCE_UNVERIFIED"
                                            if expected_source == "BOARD_RECORDED" else "QUALIFIED_MEASUREMENT_TRACE"))
        pack = self.archive / "trace"
        manifest = json.loads((pack / "manifest.json").read_bytes())
        self.assertEqual(manifest["source"], expected_source)
        self.assertEqual(manifest["stage_rows"], [40, 0, 0, 0, 0, 0, 0, 0])
        self.assertTrue(manifest["time"]["allow_wrap"])
        runner = os.getenv("FOC_CAPTURE_REPLAY_RUNNER")
        if runner:
            for command in ("validate", "explain", "replay"):
                process = subprocess.run([sys.executable, "-B", str(TOOL / "replay.py"), command,
                                          str(pack), "--runner", runner, "--json"],
                                         capture_output=True, text=True, timeout=30)
                self.assertEqual(process.returncode, 0, process.stdout + process.stderr)
                replay = json.loads(process.stdout)
                self.assertTrue(replay["trace_valid"], replay)
                self.assertEqual(replay["source"], expected_source)
                self.assertFalse(replay["applied"])
                self.assertFalse(replay["persisted"])
                if command == "replay":
                    self.assertEqual(replay["calibration_state"], "COMPLETED")
                    self.assertEqual(replay["workflow"]["stages"]["adc"]["quality"], "PASS")
                    self.assertEqual(replay["workflow"]["stages"]["adc"]["source_proxy"], 40)
                    self.assertEqual(replay["workflow"]["metrics"]["adc"]["offset_counts"], [2052, 2048, 2042])
                    self.assertFalse(replay["can_generate_candidate"])
            if expected_source == "BOARD_RECORDED":
                attestation = self.path / "mismatched-attestation.json"
                attestation.write_text(json.dumps({"manifest_sha256": "0" * 64, "source": expected_source,
                                                   "identity": self.meta["identity"], "attested_by": "test only"}),
                                       encoding="utf-8")
                process = subprocess.run([sys.executable, "-B", str(TOOL / "replay.py"), "validate",
                                          str(pack), "--runner", runner, "--attestation", str(attestation), "--json"],
                                         capture_output=True, text=True, timeout=30)
                self.assertEqual(process.returncode, 1, process.stdout + process.stderr)
                self.assertEqual(json.loads(process.stdout)["reason"], "ATTESTATION_MISMATCH")
        return output

    def test_independent_adc_witness_uses_soft06(self):
        self.assert_trace("HOST_VIRTUAL")

    def test_board_parser_branch_uses_mutated_host_fixture_without_upgrading_provenance(self):
        # Deliberately mutated Host test bytes exercise only the Board validation branch.
        self.modify([(24, 1)])
        self.meta.update(source="BOARD_RECORDED", firmware_sha256="1" * 64)
        self.witness.update(witness_source="EXTERNAL_INSTRUMENT", firmware_sha256="1" * 64)
        output = self.assert_trace("BOARD_RECORDED")
        self.assertEqual(output["provenance"], "PROVENANCE_UNVERIFIED")

    def test_missing_zero_current(self):
        self.witness["independent_zero_current"] = False
        self.assert_rejected("PRECONDITION_REQUIRED", witness=True)

    def test_qualification_from_another_capture(self):
        self.witness["capture_id"] = 19
        self.assert_rejected("PRECONDITION_REQUIRED", witness=True)

    def test_virtual_bytes_declared_board(self):
        self.meta["source"] = "BOARD_RECORDED"
        self.assert_rejected("SOURCE_MISMATCH")

    def test_forged_verification(self):
        self.meta["provenance_verified"] = True
        self.assert_rejected("METADATA_INVALID")

    def test_declared_hash_mismatch(self):
        self.meta["raw_sha256"] = "0" * 64
        self.assert_rejected("HASH_MISMATCH")

    def test_two_captures_mixed(self):
        self.modify([(ENCODER, 18)])
        self.assert_rejected("CAPTURE_ID_MISMATCH")

    def test_different_epoch(self):
        self.modify([(ENCODER + 4, 2)])
        self.assert_rejected("CLOCK_MISMATCH")

    def test_capture_id_metadata(self):
        self.meta["capture_id"] = 18
        self.assert_rejected("CAPTURE_ID_MISMATCH")

    def test_missing_row(self):
        self.modify([(44, 39)], clear=(ADC + 39 * 100, 100))
        report = self.assert_rejected("ACQUISITION_INCOMPLETE", witness=True)
        self.assertEqual(report["health"]["nominal_shortfall"]["adc"], 1)

    def test_repeated_row(self):
        self.modify([(ADC + 100 + 8, 0)])
        self.assert_rejected("ROW_SEQUENCE")

    def test_repeated_slot(self):
        self.modify([(ADC + 100 + 16, 100), (ADC + 100 + 92, 100)])
        report = self.assert_rejected("ACQUISITION_INCOMPLETE", witness=True)
        self.assertEqual(report["health"]["slot_sequence"]["repeated"], 1)

    def test_gap_in_encoder_source_sequence(self):
        self.modify([(ENCODER + 15 * 64 + 12, 216)])
        report = self.assert_rejected("ACQUISITION_INCOMPLETE", witness=True)
        self.assertEqual(report["health"]["encoder_sequence"]["missing"], 1)

    def test_out_of_order_slot(self):
        self.modify([(ADC + 100 + 16, 99), (ADC + 100 + 92, 99)])
        self.assert_rejected("SEQUENCE_ORDER")

    def test_slot_token_mismatch(self):
        self.modify([(ADC + 92, 500)])
        self.assert_rejected("SLOT_TOKEN_MISMATCH")

    def test_time_reversal(self):
        timestamp = struct.unpack_from("<I", self.raw.read_bytes(), ADC + 12)[0]
        self.modify([(ADC + 100 + 12, timestamp - 1)])
        self.assert_rejected("TIME_ORDER")

    def test_half_range_ambiguity(self):
        timestamp = struct.unpack_from("<I", self.raw.read_bytes(), ADC + 12)[0]
        self.modify([(ADC + 24, (timestamp - (1 << 31)) & 0xFFFFFFFF)])
        self.assert_rejected("TIME_ORDER")

    def test_rank_mapping(self):
        self.modify([(68, 0x04050601)])
        self.assert_rejected("RANK_MAP")

    def test_adc_invalid(self):
        self.modify([(ADC + 36, 131), (ADC + 40, 7)])
        report = self.assert_rejected("ACQUISITION_INCOMPLETE", witness=True)
        self.assertEqual(report["health"]["adc_invalid"], 1)

    def test_adc_deadline(self):
        timestamp = struct.unpack_from("<I", self.raw.read_bytes(), ADC + 12)[0]
        self.modify([(ADC + 24, timestamp - 81)])
        self.assert_rejected("ADC_DEADLINE")

    def test_encoder_frame_error(self):
        self.modify([(ENCODER + 40, 2), (ENCODER + 44, 2), (ENCODER + 48, 1)])
        report = self.assert_rejected("ACQUISITION_INCOMPLETE", witness=True)
        self.assertEqual(report["health"]["encoder_errors"], 1)
        self.assertEqual(report["encoder"][0]["raw_word"], 16384)

    def test_spi_timeout(self):
        self.modify([(ENCODER + 20, 0), (ENCODER + 32, 0), (ENCODER + 36, 1),
                     (ENCODER + 40, 1), (ENCODER + 44, 1), (ENCODER + 48, 1)])
        report = self.assert_rejected("ACQUISITION_INCOMPLETE", witness=True)
        self.assertEqual(report["health"]["encoder_errors"], 1)

    def test_overflow(self):
        self.modify([(52, 1), (56, 2)])
        self.assert_rejected("ACQUISITION_INCOMPLETE", witness=True)

    def test_cancelled_even_with_all_rows(self):
        self.modify([(16, 2)])
        self.assert_rejected("ACQUISITION_INCOMPLETE", witness=True)

    def test_host_interrupted_or_short_swd_dump(self):
        self.raw.write_bytes(self.raw.read_bytes()[:-1])
        self.assert_rejected("RAW_SIZE")

    def test_modified_raw_bytes(self):
        raw = bytearray(self.raw.read_bytes())
        raw[ADC + 29] ^= 1
        self.raw.write_bytes(raw)
        self.assert_rejected("CRC_MISMATCH")

    def test_unknown_format(self):
        self.modify([(4, 2)])
        self.assert_rejected("RAW_VERSION")

    def test_output_applied_forgery(self):
        self.modify([(ADC + 76, 256 | 512 | 1)])
        self.assert_rejected("OUTPUT_LOCK_VIOLATION")


if __name__ == "__main__":
    unittest.main(verbosity=2)